<?php
declare(strict_types=1);
require_once __DIR__ . '/../../../app/helpers.php';
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
function api_error(int $code,string $message): never { http_response_code($code); echo json_encode(['error'=>$message],JSON_UNESCAPED_UNICODE); exit; }
if($_SERVER['REQUEST_METHOD']!=='GET')api_error(405,'method_not_allowed');
$auth=(string)($_SERVER['HTTP_AUTHORIZATION']??'');if(!preg_match('/^Bearer\s+(frb_[a-f0-9]{64})$/',$auth,$m))api_error(401,'missing_or_invalid_bearer_token');
try{$pdo=db();$q=$pdo->prepare("SELECT k.id,k.partner_id,k.scopes_json,k.expires_at,k.revoked_at,u.role AS partner_role FROM partner_api_keys k JOIN users u ON u.id=k.partner_id WHERE k.key_hash=? AND u.is_active=1 AND u.verification_status='verified' LIMIT 1");$q->execute([hash('sha256',$m[1])]);$key=$q->fetch();if(!$key||$key['revoked_at']||($key['expires_at']&&strtotime($key['expires_at'])<=time()))api_error(401,'invalid_or_expired_key');$scopes=json_decode((string)$key['scopes_json'],true)?:[];if(!in_array('impact:read',$scopes,true))api_error(403,'insufficient_scope');$count=$pdo->prepare('SELECT COUNT(*) FROM partner_api_request_logs WHERE api_key_id=? AND requested_at>=NOW()-INTERVAL 1 MINUTE');$count->execute([$key['id']]);if((int)$count->fetchColumn()>=60)api_error(429,'rate_limit_exceeded');$pdo->prepare('INSERT INTO partner_api_request_logs(api_key_id,endpoint,http_status) VALUES(?,?,200)')->execute([$key['id'],'impact']);$pdo->prepare('DELETE FROM partner_api_request_logs WHERE requested_at<NOW()-INTERVAL 1 DAY')->execute();if(in_array($key['partner_role'],['restaurant','event_organizer'],true)){$r=$pdo->prepare("SELECT COUNT(*) AS completed_listings,COALESCE(SUM(x.quantity_kg),0) AS quantity_kg FROM (SELECT DISTINCT sf.id,sf.quantity_kg FROM surplus_food sf JOIN donation_requests dr ON dr.surplus_food_id=sf.id WHERE sf.restaurant_id=? AND dr.status IN ('delivered','completed')) x");}else{$r=$pdo->prepare("SELECT COUNT(*) AS completed_listings,COALESCE(SUM(x.quantity_kg),0) AS quantity_kg FROM (SELECT DISTINCT sf.id,sf.quantity_kg FROM surplus_food sf JOIN donation_requests dr ON dr.surplus_food_id=sf.id WHERE dr.requested_by=? AND dr.status IN ('delivered','completed')) x");}$r->execute([$key['partner_id']]);echo json_encode(['data'=>$r->fetch(),'scope'=>'impact:read','generated_at'=>date(DATE_ATOM)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}catch(Throwable $e){error_log('FoodRescue impact API error: '.$e->getMessage());api_error(503,'service_unavailable');}
